function extract($, ctx) {
  const items = [];
  const seen = new Set();

  const $menuRoot = $('#menu-root');
  if (!$menuRoot.length) return items;

  $menuRoot.find('.menu-group').each((_, sectionEl) => {
    const $section = $(sectionEl);
    const sectionTitle = cleanText($section.find('.menu-group__title').text());

    $section.find('.dish').each((_, dishEl) => {
      const $dish = $(dishEl);
      const name = cleanText($dish.find('.dish__name').text());
      if (!name) return;

      const $desc = $dish.find('.dish__desc');
      const description = $desc.length ? cleanText($desc.text()) : null;

      const $price = $dish.find('.dish__price');
      const price = $price.length ? parsePrice($price.text()) : null;

      const key = `${sectionTitle}|${name}|${description}|${price}`;
      if (seen.has(key)) return;
      seen.add(key);

      items.push({ section: sectionTitle, name, description, price });
    });
  });

  return items;
}

